{
  "try_first": "gear_icon",
  "why": "The gear (settings) icon most commonly holds card-specific settings like card controls, security, and travel/international options.",
  "steps_after_tapping_gear": [
    "Look for entries named Card settings, Card controls, Security, Notifications, or International use.",
    "If you see Card controls or Card settings, open it and scan for Travel notice, Travel alerts, Travel plans, or International use.",
    "If a Travel/International option appears, open it, add destination (Japan), start and end dates, any cities/notes, select the Platinum Rewards Card if prompted, and Save/Submit."
  ],
  "if_gear_does_not_show_travel_options": {
    "try_next": "three_dot_menu (More)",
    "steps": [
      "Open the three-dot menu and look for Manage card, Settings, Controls, Security, Help, or Support.",
      "If you see Help/Support, open it and choose In‑app chat or Add travel notice (if offered). Agents in chat can add the notice if the UI option isn’t present."
    ]
  },
  "if_you_still_can't_find_it": {
    "options": [
      "Use the in‑app secure chat to ask an agent to add a travel notice for your Platinum Rewards Card.",
      "Visit rhobank.com/help for contact options.",
      "Call 1‑800‑RHO‑BANK (KB lists it) — note: the KB does not list an international phone number and U.S. toll‑free numbers may not work from Japan, so prefer in‑app chat or the website while abroad."
    ]
  },
  "what_to_have_ready_for_the_notice": [
    "Trip dates (start and end)",
    "Destination: country (Japan) and any cities you want listed",
    "Which card(s) to cover (Platinum Rewards Card)",
    "Optional notes about expected merchants or large purchase amounts"
  ],
  "confirmation_check": "After saving, confirm you get an on‑screen success message, push notification, or an in‑app message from support stating the travel notice was added.",
  "next_step_offer": "Tell me what options you see after you tap the gear or More menu and I’ll guide the exact next tap."
}

{
  "short_answer": "Enable the International transactions toggle, but also add a travel notice (via in‑app chat or support) and enable transaction/international alerts to reduce the chance of declines.",
  "why": "Turning on International transactions allows purchases abroad, but it does not guarantee the fraud-monitoring system won’t flag unusual activity. A travel notice or an agent note on your account (and having alerts enabled) helps the bank recognize legitimate international charges.",
  "recommended_steps": [
    {
      "step": "Enable International transactions",
      "what_to_do": "In Card Controls, turn the “International transactions” toggle ON (you already have the Card Controls screen open)."
    },
    {
      "step": "Enable alerts",
      "what_to_do": "Go back and open Alerts & Notifications. Turn on transaction alerts and any international-use or push/email alerts so you receive time-sensitive prompts during travel."
    },
    {
      "step": "Add a travel notice (recommended)",
      "what_to_do": "If you don’t see an in‑app Travel Notice option, open the in‑app secure chat (Help/Support) and ask an agent to add a travel notice for your Platinum Rewards Card with your trip dates and cities. The KB recommends using in‑app chat if the UI option isn’t present."
    },
    {
      "step": "Confirm",
      "what_to_do": "Ask the agent for confirmation that the travel notice was added, and look for an in‑app message or success confirmation before you rely on the card abroad."
    }
  ],
  "timing": "The KB does not give a required lead time. To be safe, add the notice as soon as you have firm travel dates — ideally several days before departure.",
  "multiple_cities": "Yes. You can include multiple cities. If the app only accepts a single location field, list \"Japan\" and include the specific cities in the chat/notes to the agent so your full itinerary is recorded.",
  "sample_chat_message": "Hi — please add a travel notice for my Platinum Rewards Card. I will be traveling to Japan from [START_DATE] to [END_DATE]. Cities: [Tokyo, Kyoto, Osaka, etc.]. Please enable international use and note these dates/cities on my account. Thank you.",
  "other_tips": [
    "Keep your phone number and email on file up to date so you receive fraud verification prompts.",
    "Bring a backup payment method in case a charge is declined despite the notice.",
    "If you need, I can help you draft the chat message with your exact dates and cities (don’t share sensitive card numbers here)."
  ],
  "next_step_offer": "Would you like me to draft the exact chat message with your travel dates and cities to paste into the in‑app chat?"
}
